// Gadget Style product data. Single source of truth for products, categories,
// and blog posts. Invariants enforced by scripts/validate-data.ts — run
// `pnpm check:data` before committing changes.

export interface Product {
  id: number;
  title: string;
  slug: string;
  description: string;
  price: number;
  category: string;
  categorySlug: string;
  image: string;
  images: string[];
  rating: number;
  reviewCount: number;
  asin: string;
  affiliateUrl: string;
  gadgetFlowUrl: string;
  tags: string[];
  dateAdded: string;
  isFeatured: boolean;
  isTrending: boolean;
  specs: Record<string, string>;
  /**
   * When true, the product is hidden from the public site (category pages,
   * featured, trending, search, direct slug lookup) and is exempt from strict
   * ASIN / price / affiliate-URL validation. Use for products that are not
   * yet live on Amazon, pending verification, or otherwise not ready to ship.
   * Drafts must still have the required fields populated so they can be
   * promoted to live with a single flag flip.
   */
  isDraft?: boolean;
  /**
   * Where the "buy" button sends the user. Defaults to "amazon" (uses
   * `affiliateUrl`, a canonical amazon.com /dp/<ASIN> link with tag=gadgetstyle01-20).
   *
   * Set to "external" for products that aren't on Amazon (Kickstarter,
   * brand-direct, international-only, pre-launch). Validator relaxes the
   * Amazon-URL requirement; product still appears in catalog but doesn't
   * earn affiliate revenue. Replicates Gadget Flow's multi-source model.
   */
  destination?: "amazon" | "external";
  /**
   * Destination URL when `destination: "external"`. Any buyable URL —
   * manufacturer's site, crowdfunding campaign, Gadget Flow article. Ignored
   * when destination is unset or "amazon".
   */
  externalUrl?: string;
  /**
   * Optional product videos — YouTube/Vimeo iframe URLs or direct .mp4 URLs.
   * Rendered alongside the image gallery on the product page.
   */
  videos?: string[];
}

export interface Category {
  name: string;
  slug: string;
  description: string;
  icon: string;
  productCount: number;
  image: string;
}

export interface BlogPost {
  id: number;
  title: string;
  slug: string;
  excerpt: string;
  content: string;
  image: string;
  author: string;
  date: string;
  readTime: string;
  tags: string[];
}

