    specs: { "Lock Type": "Keyless touchscreen deadbolt", "Connectivity": "Wi-Fi, Bluetooth, Z-Wave", "Battery": "4x AA (up to 6 months)", "Compatibility": "Alexa, Google, HomeKit", "Auto-Lock": "Yes, adjustable timer" },
