    specs: { "Driver": "8.4mm Dynamic Driver X", "ANC": "Integrated Processor V2", "Battery Life": "8 hrs (buds), 24 hrs (case)", "Codec": "LDAC, DSEE Extreme", "Weight": "0.19 oz per earbud", "IP Rating": "IPX4" },
