    specs: { "Sensor": "HERO 25K", "Resolution": "100–25,600 DPI", "Switches": "LIGHTFORCE hybrid optical-mechanical", "Weight": "3.74 oz (106g)", "Battery Life": "Up to 130 hours", "Connectivity": "LIGHTSPEED wireless, USB-C" },
