    specs: { "Drivers": "40mm neodymium", "Frequency Response": "10–40,000 Hz", "ANC": "4-mic hybrid ANC", "Battery Life": "Dual hot-swappable batteries, 22 hrs each", "Connectivity": "2.4 GHz wireless + Bluetooth", "DAC": "Parametric EQ, GameDAC Gen 2" },
