    specs: { "Switches": "Razer Orange Tactile Mechanical", "Layout": "75% compact", "Lighting": "Razer Chroma RGB per-key", "Connectivity": "USB-C wired", "Keycaps": "Doubleshot ABS", "Features": "Rotary knob, magnetic wrist rest" },
