    tags: ["Stream Deck", "Streaming", "Content Creation", "Elgato"],
    dateAdded: "2025-06-02",
    isFeatured: true,
    isTrending: false,
    specs: { "Keys": "15 customizable LCD keys", "Display": "72 x 72 px per key", "Connectivity": "USB 2.0", "Dimensions": "4.6\" x 3.3\" x 1.0\"", "Weight": "5.5 oz (156g)", "Compatibility": "Windows 10+, macOS 10.15+" },
