    specs: { "Capture Resolution": "4K30 / 1080p60 HDR10 passthrough", "Interface": "USB 3.0 Type-C", "Encoding": "H.264/H.265 hardware", "Latency": "Near-zero latency passthrough", "Compatibility": "PC, Mac, PlayStation, Xbox", "VRR Support": "Yes (passthrough)" },
