    specs: { "Display": "46mm LTPO3 OLED Always-On", "Chip": "Apple S10 SiP", "Sensors": "Heart rate, SpO2, ECG, temperature", "Water Resistance": "WR50 (50 meters)", "Battery Life": "Up to 18 hours", "Connectivity": "GPS, Bluetooth 5.3, Wi-Fi, UWB" },
