    specs: { "Sensors": "Infrared PPG, NTC temperature, 3D accelerometer", "Battery Life": "Up to 7 days", "Water Resistance": "100 meters", "Weight": "4–6 grams", "Material": "Titanium", "Connectivity": "Bluetooth 5.0 LE" },
