    isFeatured: false,
    isTrending: false,
    specs: { "Display": "1.2-inch always-on MIP", "Battery Life": "24 days (watch), 38 hrs (GPS)", "Weight": "1.34 oz (39g) with nylon band", "Navigation": "Dual-frequency GPS (5 systems)", "Water Rating": "5 ATM", "Sensors": "Optical HR, SpO2, barometric altimeter" },
