    specs: { "Capacity": "1,264Wh LiFePO4", "Output Power": "2,000W (4,000W surge)", "Ports": "3x AC, 2x USB-C (100W), 2x USB-A", "Charging": "Solar (800W max), AC (1,200W)", "Weight": "32.8 lbs (14.8 kg)", "Cycle Life": "4,000+ cycles to 70%" },
