    specs: { "Power Output": "50W solar panel", "Cell Type": "Monocrystalline", "Ports": "8mm, USB-A, USB-C", "Weight": "8.2 lbs (3.7 kg)", "Dimensions": "21.75\" x 15.25\" (unfolded)", "Chainable": "Yes, up to 200W" },
