    images: ["/images/mirrored/product_59_img1_eb63e06f.jpg", "/images/mirrored/product_59_img2_ec96824f.jpg", "/images/mirrored/product_59_img3_8e3480af.jpg", "/images/mirrored/product_59_img4_8b7846b1.jpg"],
