    specs: { "Display": "3.0\" sunlight-readable color", "Battery Life": "Up to 180 hours (expedition mode)", "Navigation": "Multi-band GPS, topo maps", "Memory": "16 GB internal", "Water Rating": "IPX7", "Weight": "8.0 oz (230g)" },
