    tags: ["Headlamp", "Waterproof", "Camping", "Hiking"],
    dateAdded: "2025-02-06",
    isFeatured: true,
    isTrending: false,
    specs: { "Output": "400 lumens (max)", "Beam Distance": "100 meters", "Battery": "3x AAA or rechargeable", "Modes": "Spot, flood, red night vision", "Weight": "2.8 oz (80g) with batteries", "Water Rating": "IPX8" },
