    specs: { "Capacity": "24,000mAh", "Max Output": "140W USB-C PD 3.1", "Ports": "2x USB-C, 1x USB-A", "Display": "Smart digital display", "Weight": "1.42 lbs (645g)", "Recharge Time": "58 minutes (140W input)" },
