    affiliateUrl: "https://www.amazon.com/dp/B09GK8LBWS?tag=gadgetstyle01-20",
    gadgetFlowUrl: "https://thegadgetflow.com/product/caldigit-ts4-thunderbolt4-dock-gives-you-18ports-along-with-98w-laptop-charging/",
    tags: ["Thunderbolt Dock", "USB-C Hub", "CalDigit", "18 Ports"],
    dateAdded: "2025-05-09",
    isFeatured: false,
    isTrending: false,
    specs: { "Ports": "18 total", "Thunderbolt": "Thunderbolt 4 (40Gbps)", "Display Support": "Dual 6K or single 8K", "Power Delivery": "98W to host laptop", "Ethernet": "2.5 Gigabit", "Storage": "SD 4.0 UHS-II, microSD" },
