    tags: ["Tech Pouch", "Organizer", "Bellroy", "EDC"],
    dateAdded: "2025-07-11",
    isFeatured: false,
    isTrending: false,
    specs: { "Material": "Recycled woven fabric", "Dimensions": "9.1\" x 4.7\" x 2.2\"", "Weight": "4.9 oz (140g)", "Pockets": "Elastic loops, mesh zip pocket, pen slot", "Closure": "YKK zip" },
