    specs: { "Charging": "MagSafe 15W + Apple Watch fast charge", "Material": "Metal + glass surface", "Compatibility": "iPhone 12+, Apple Watch Series 7+", "Cable": "USB-C (included)", "Weight": "11.6 oz (330g)" },
