    specs: { "Output": "65W USB-C PD", "Technology": "GaN II", "Ports": "1x USB-C", "Dimensions": "1.7\" x 1.6\" x 1.6\"", "Weight": "3.9 oz (112g)", "Compatibility": "MacBook Pro, iPhone, iPad, Galaxy" },
