    specs: { "Connection": "USB-C", "Lag": "30ms", "Screen": "3.5-inch high-res touchscreen", "Compatibility": "iPhone 15 and later, Android devices with USB-C and DisplayPort (DP) Alt Mode", "Special Feature": "One-tap mirroring" },
