    specs: { "Capacity": "256GB", "Interface": "USB 3.2 Gen 1", "Connector": "Lightning and USB-C", "Sequential Read Performance": "90MB/s", "Sequential Write Performance": "10MB/s", "Warranty": "2-Year Limited Warranty" },
