    specs: { "Brand": "Amazon", "Model": "Kindle Scribe (newest model)", "Digital storage capacity": "64 GB", "Display size": "11 inches", "Device thickness": "5.4 mm", "Device weight": "400 g", "Included stylus": "Premium Pen, no charging required" },
