    affiliateUrl: "https://www.amazon.com/dp/B07KRY43KN?tag=gadgetstyle01-20",
    gadgetFlowUrl: "https://thegadgetflow.com/product/amazon-echo-glow/",
    tags: ["Gadgets for Kids"],
