    affiliateUrl: "https://www.amazon.com/dp/B0B1N5HW22?tag=gadgetstyle01-20",
    gadgetFlowUrl: "https://thegadgetflow.com/product/blink-outdoor-4th-generation-outdoor-wireless-security-camera/",
    tags: ["Amazon Alexa Gadgets"],
    dateAdded: "2026-04-20",
    isFeatured: false,
    isTrending: false,
    specs: { "Audio": "2 Way", "Battery Life": "2 Yrs", "Design": "Wireless" },
