    specs: { "Voice Assistant": "Amazon Alexa", "Calls": "Open-Ear Audio", "Water Resistance": "IPX4", "Pairing": "Multi-Point", "Style": "Cruiser, Sprinter", "Hinges": "German-Engineered" },
