    asin: "B09N6D5SDX",
    affiliateUrl: "https://www.amazon.com/dp/B09N6D5SDX?tag=gadgetstyle01-20",
    gadgetFlowUrl: "https://thegadgetflow.com/product/blink-mini-pan-tilt-rotating-indoor-security-cam-offers-2way-audio-motion-detection/",
    tags: ["Amazon Alexa Gadgets"],
