    isTrending: false,
    specs: { "Colors": "Blue, Purple, Red", "Dimensions": "6.4\" L x 7.9\" W x 1.1\" H", "Weight": "15.1 oz", "CPU": "Quad-Core 2.0 GHz", "RAM": "2 GB", "Storage": "16 GB" },
