    isFeatured: false,
    isTrending: false,
    specs: { "Display": "7\"", "Resolution": "1024 x 600", "Battery Life": "10 Hrs", "Storage": "16 GB, 32 GB", "RAM": "2 GB", "Dimensions": "7.11” x 4.63” x 0.38”", "Colors": "Black, Denim, Rose" },
