    images: ["/images/mirrored/Amazon-Blink-Floodlight-Cam-Wireless-Outdoor-Camera-01.jpg", "/images/mirrored/Amazon-Blink-Floodlight-Cam-Wireless-Outdoor-Camera-02.jpg", "/images/mirrored/Amazon-Blink-Floodlight-Cam-Wireless-Outdoor-Camera-03.jpg", "/images/mirrored/Amazon-Blink-Floodlight-Cam-Wireless-Outdoor-Camera-04.jpg", "/images/mirrored/Amazon-Blink-Floodlight-Cam-Wireless-Outdoor-Camera-05.jpg", "/images/mirrored/Amazon-Blink-Floodlight-Cam-Wireless-Outdoor-Camera-06.jpg", "/images/mirrored/Amazon-Blink-Floodlight-Cam-Wireless-Outdoor-Camera-07.jpg"],
