    specs: { "Display": "6.8\"", "Storage": "8 GB", "Battery Life": "10 Weeks", "Charging Time": "2.5 Hours", "Weight": "7.23 oz", "Dimensions": "4.9” x 6.9” x .32”", "Color": "Black" },
