    specs: { "Screen Size": "65\"", "Resolution": "3840 x 2160", "Display": "4K UHD", "Backlight Type": "Direct LED", "Refresh Rate": "60 Hz", "OS": "Fire TV OS", "Front Finish": "Gray Metal" },
