    specs: { "Dimensions": "3.66\" L x 6.10\" W x 3.97\" H", "Capacity": "12 oz.", "Automatic": "Yes", "Soap Type": "Liquid", "Battery": "Rechargeable", "Material": "Plastic", "Compatibility": "Alexa", "Timer": "20 Secs" },
