    specs: { "Display": "10.1\" 1080p Full HD", "Storage": "32 GB", "CPU": "Octa-Core 2.0 GHz", "Battery Life": "12 Hrs", "Ports": "USB-C 2.0", "Front-Facing Camera": "2 MP", "Rear-Facing Camera": "5 MP" },
