    specs: { "Display": "10.1\" 1080p Full HD", "Storage": "32 GB, 64 GB", "RAM": "3 GB", "Battery Life": "12 Hrs", "CPU": "Octa-Core 2.0 GHz", "Colors": "Black, Denim, Lavender, Olive" },
