    specs: { "Smartphone Compatibility": "Android 9.0+, iOS 13.6+", "Connectivity": "Bluetooth 5.0", "Microphones": "2", "Speakers": "4", "Battery Life": "14 Hrs", "Audio": "Open Ear", "Colors": "Classic Black, Horizon Blue, Modern Tortoise" },
