// Helper functions. Every public-facing helper filters out drafts — drafts
// are only visible to maintainers via the raw `products` export.
const isLive = (p: Product) => !p.isDraft;

export function getProductBySlug(slug: string): Product | undefined {
  return products.find(p => p.slug === slug && isLive(p));
}

export function getProductsByCategory(categorySlug: string): Product[] {
  return products.filter(p => p.categorySlug === categorySlug && isLive(p));
}

export function getFeaturedProducts(): Product[] {
  return products.filter(p => p.isFeatured && isLive(p));
}

export function getTrendingProducts(): Product[] {
  return products.filter(p => p.isTrending && isLive(p));
}

export function getNewProducts(count: number = 8): Product[] {
  return products
    .filter(isLive)
    .sort((a, b) => new Date(b.dateAdded).getTime() - new Date(a.dateAdded).getTime())
    .slice(0, count);
}

export function searchProducts(query: string): Product[] {
  const q = query.toLowerCase();
  return products.filter(p =>
    isLive(p) && (
      p.title.toLowerCase().includes(q) ||
      p.description.toLowerCase().includes(q) ||
      p.tags.some(t => t.toLowerCase().includes(q)) ||
      p.category.toLowerCase().includes(q)
    )
  );
}

export function getCategoryBySlug(slug: string): Category | undefined {
  return categories.find(c => c.slug === slug);
}

export function getBlogPostBySlug(slug: string): BlogPost | undefined {
  return blogPosts.find(p => p.slug === slug);
}
